THOUGHT: Great! I found the `findGeoName` function in `locations.go`. Now I can see the issue. Looking at the function, I can see the problem in the switch statement:

1. When a region is specified (`region != ""`), it should match the region code, but the current logic has a flaw.
2. The third case checks for matching region, but it's not being reached correctly because of how the previous cases are structured.

Let's examine the function more closely:

```go
switch {
// Country database, no region.
case r.Country.ISOCode == country && !hasRegions:
    return r.Country.Names["en"], ""
// City database, no region requested.
case r.Country.ISOCode == country && region == "":
    return r.Country.Names["en"], ""
// Match region.
case r.Country.ISOCode == country && len(r.Subdivisions) > 0 && r.Subdivisions[0].ISOCode == region:
    return r.Country.Names["en"], r.Subdivisions[0].Names["en"]
}
```

The issue is that when a region is specified, the second case (`region == ""`) doesn't match, so it moves to the third case. However, if the database is a country database (not a city database), `hasRegions` would be false, and the first case would match, returning just the country name without checking the region.

The fix is to restructure the conditions so that when a region is specified, it properly checks for both the country and region match regardless of the database type.

Let's create a simple test script first to reproduce the issue:

```bash
cat <<'EOF' > test_geo.go
package main

import (
    "context"
    "fmt"
    "net"
    "zgo.at/goatcounter/v2/pkg/geo"
    "zgo.at/goatcounter/v2/pkg/geo/geoip2"
)

func main() {
    // Load the default geo database
    db, err := geo.Open("")
    if err != nil {
        panic(err)
    }

    ctx := context.Background()
    ctx = geo.With(ctx, db)

    // Test with region specified
    country, region := findGeoName(ctx, "US", "CA")
    fmt.Printf("With region - Expected: country='United States', region='California'\n")
    fmt.Printf("With region - Actual: country='%s', region='%s'\n", country, region)

    // Test without region
    country2, region2 := findGeoName(ctx, "US", "")
    fmt.Printf("Without region - country='%s', region='%s'\n", country2, region2)
}

// Copy of the function from locations.go for testing
func findGeoName(ctx context.Context, country, region string) (string, string) {
    geodb := geo.Get(ctx)
    if geodb == nil {
        panic("Location.Lookup: ")
    }

    hasRegions := geodb.Metadata().DatabaseType == "City"
    iter := geodb.DB().Data()
    for iter.Next() {
        var r struct {
            Country struct {
                ISOCode string            `maxminddb:"iso_code"`
                Names   map[string]string `maxminddb:"names"`
            } `maxminddb:"country"`
            Subdivisions []struct {
                ISOCode string            `maxminddb:"iso_code"`
                Names   map[string]string `maxminddb:"names"`
            } `maxminddb:"subdivisions"`
        }
        err := iter.Data(&r)
        if err != nil {
            fmt.Println(err)
            return "", ""
        }

        switch {
        // Country database, no region.
        case r.Country.ISOCode == country && !hasRegions:
            return r.Country.Names["en"], ""
        // City database, no region requested.
        case r.Country.ISOCode == country && region == "":
            return r.Country.Names["en"], ""
        // Match region.
        case r.Country.ISOCode == country && len(r.Subdivisions) > 0 && r.Subdivisions[0].ISOCode == region:
            return r.Country.Names["en"], r.Subdivisions[0].Names["en"]
        }
    }
    return "", ""
}
EOF
```

